using System;using System.IO;using IdleIntelligence.Core;using UnityEngine;
namespace IdleIntelligence.Runtime {
 public sealed class CrashRecording:MonoBehaviour {
  public CrashLedger Ledger{get;private set;}public CrashSession Previous{get;private set;}public bool PreviousUnexpected{get;private set;}string path;GameRuntime game;double nextHeartbeat,lastFrame;long frames;bool paused;static double Now=>DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
  public void Initialize(GameRuntime runtime){game=runtime;path=game.SavePath+".diagnostics.json";if(File.Exists(path)){try{if(new FileInfo(path).Length>32L*1024*1024)throw new FormatException("Oversized diagnostics");string raw=File.ReadAllText(path);var old=JsonUtility.FromJson<CrashSession>(raw);if(old==null||old.version!=1||old.actions==null||old.failures==null||string.IsNullOrEmpty(old.sessionId))throw new FormatException("Unknown diagnostics");Previous=old;PreviousUnexpected=!old.cleanExit;if(PreviousUnexpected){old.failures=System.Linq.Enumerable.ToArray(System.Linq.Enumerable.TakeLast(System.Linq.Enumerable.Concat(old.failures,new[]{new CrashFailure{at=Now,kind="unexpected-session-end",message="The previous session had no clean end marker; its cause is unknown.",stack=""}}),20));if(!File.Exists(path+".previous"))File.WriteAllText(path+".previous",JsonUtility.ToJson(old));}if(File.Exists(path+".previous")){try{if(new FileInfo(path+".previous").Length>32L*1024*1024)throw new FormatException("Oversized diagnostics archive");var archived=JsonUtility.FromJson<CrashSession>(File.ReadAllText(path+".previous"));if(archived!=null&&archived.version==1&&archived.failures!=null)Previous=archived;}catch{}}string copy=path+".session-original-"+Guid.NewGuid().ToString("N");File.Copy(path,copy,false);}catch{try{File.Copy(path,path+".invalid-original-"+Guid.NewGuid().ToString("N"),false);}catch{} }}Ledger=new CrashLedger(Now,Guid.NewGuid().ToString("N"),Run(),Application.platform+" / "+SystemInfo.operatingSystem,Write);lastFrame=Time.realtimeSinceStartupAsDouble;Application.logMessageReceived+=Log;}
  string Run()=>game.State.Meta.resets+":"+game.State.Prestige.resets;
  void Write(CrashSession state){using(PerformanceMarkers.Diagnostic.Auto()){string temp=path+".pending";File.WriteAllText(temp,JsonUtility.ToJson(state));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}}
  void Update(){if(Ledger==null)return;double now=Time.realtimeSinceStartupAsDouble,gap=(now-lastFrame)*1000;lastFrame=now;frames++;if(!paused&&gap>JournalCatalog.HeartbeatGapMilliseconds)Ledger.Failure("ui-heartbeat-missed","Main-loop gap observed after resume: "+gap.ToString("F1")+" ms","",Now);if(now>=nextHeartbeat){Ledger.Heartbeat(Now,frames);nextHeartbeat=now+1;}}
  void Log(string condition,string stack,LogType kind){if(Ledger!=null&&(kind==LogType.Exception||kind==LogType.Error||kind==LogType.Assert))Ledger.Failure("unhandled-exception",condition,stack,Now);}
  void OnApplicationPause(bool value){paused=value;lastFrame=Time.realtimeSinceStartupAsDouble;Ledger?.Visibility(value?"background":"foreground",Now);}
  void OnApplicationFocus(bool value){paused=!value;lastFrame=Time.realtimeSinceStartupAsDouble;Ledger?.Visibility(value?"blur":"focus",Now);}
  void OnApplicationQuit(){Ledger?.CleanExit(Now);}void OnDestroy(){Application.logMessageReceived-=Log;Ledger?.CleanExit(Now);}
 }
}
